from collections import deque, Counter

def comps(grid):
 h,w=len(grid),len(grid[0]); seen=set(); out=[]
 for r in range(h):
  for c in range(w):
   if (r,c) in seen: continue
   v=grid[r][c]; q=[(r,c)]; seen.add((r,c)); cells=[]
   while q:
    a,b=q.pop(); cells.append((a,b))
    for x,y in ((a-1,b),(a+1,b),(a,b-1),(a,b+1)):
     if 0<=x<h and 0<=y<w and (x,y) not in seen and grid[x][y]==v:
      seen.add((x,y)); q.append((x,y))
   out.append((v,len(cells), min(x for x,y in cells), max(x for x,y in cells), min(y for x,y in cells), max(y for x,y in cells)))
 return sorted(out,key=lambda t:t[1],reverse=True)
